const {chromium}=require('C:/Temp/openclaw-playwright/node_modules/playwright');
const http=require('http'),fs=require('fs'),path=require('path');
const root=path.resolve('frontend/dist/booking-mobile-final');
const server=http.createServer((req,res)=>{let f=path.join(root,decodeURIComponent(req.url.split('?')[0]));if(!fs.existsSync(f)||fs.statSync(f).isDirectory())f=path.join(root,'index.html');res.setHeader('Content-Type',f.endsWith('.js')?'text/javascript':f.endsWith('.css')?'text/css':f.endsWith('.html')?'text/html':'application/octet-stream');res.end(fs.readFileSync(f));});
(async()=>{await new Promise(r=>server.listen(4319,'127.0.0.1',r));const browser=await chromium.launch({channel:'msedge',headless:true});try{const context=await browser.newContext({viewport:{width:390,height:844}});const identity={_id:'visual-user',role:'ADMIN',name:'Preview',lastname:'Admin',first_password_changed:true};const token='test.'+Buffer.from(JSON.stringify({...identity,exp:Math.floor(Date.now()/1000)+3600})).toString('base64url')+'.test';await context.addCookies([{name:'identity',value:JSON.stringify(identity),url:'http://127.0.0.1:4319'},{name:'token',value:token,url:'http://127.0.0.1:4319'}]);const page=await context.newPage();await page.route('**/*',async route=>{const u=new URL(route.request().url());if(u.origin==='http://127.0.0.1:4319'&&!u.pathname.startsWith('/api'))return route.continue();return route.fulfill({json:{success:true,status:'success',data:{docs:[],notifications:[]}}});});await page.goto('http://127.0.0.1:4319/#/home/visual-condo');await page.waitForSelector('app-home');await page.evaluate(()=>{const c=ng.getComponent(document.querySelector('app-home'));c._messageService.clear();c.showComponent('booking');ng.applyChanges(c);});await page.waitForSelector('app-booking-area');await page.evaluate(()=>{const c=ng.getComponent(document.querySelector('app-booking-area'));c.canDeleteBookings=true;c.bookingHistory=[];c.selectedRow=[];c.loading=false;ng.applyChanges(c);});await page.locator('.booking-history-card').scrollIntoViewIfNeeded();for(const width of [320,390]){await page.setViewportSize({width,height:900});await page.locator('.booking-history-card').screenshot({path:path.join(root,'empty-'+width+'.png')});console.log('EMPTY',width,await page.getByText('No bookings found',{exact:true}).isVisible());}await page.evaluate(()=>{const c=ng.getComponent(document.querySelector('app-booking-area'));c.bookingHistory=Array.from({length:12},(_,i)=>({id:'b'+i,alias:'Palm Residence',bookingName:'Resident '+(i+1),unit:'A-'+i,area:'Community pool',checkIn:'Sep 20, 2026, 9:00 AM',checkOut:'Sep 20, 2026, 11:00 AM',checkOutAt:'2026-09-20',status:'reserved',verified:true,visitorNumber:2}));ng.applyChanges(c);});for(const width of [320,390,1280]){await page.setViewportSize({width,height:900});await page.locator('.booking-toolbar').scrollIntoViewIfNeeded();await page.screenshot({path:path.join(root,'bookings-'+width+'.png')});console.log(JSON.stringify(await page.evaluate(()=>({width:innerWidth,overflow:document.documentElement.scrollWidth>innerWidth,toolbarWidth:document.querySelector('.booking-toolbar').scrollWidth,available:document.querySelector('.booking-toolbar').clientWidth,labelDisplay:getComputedStyle(document.querySelector('.booking-field-label')).display,selection:getComputedStyle(document.querySelector('.booking-selection-cell')).display}))))}}finally{await browser.close();server.close();}})().catch(e=>{console.error(e);server.close();process.exitCode=1});
